                nisa.nc_matmul(dst=psc[r], stationary=oht[r][:, t, :], moving=hi[r], accumulate=False)
                nisa.nc_matmul(dst=psc[r], stationary=oht[r][:, t, :], moving=mid[r], accumulate=True)
